L["After visiting a trainer, a small window lists the abilities you just learned. Abilities from a tome or a quest show a moment after you learn them. Drag one from the window onto your bars."] = "Después de visitar a un instructor, una pequeña ventana enumera las habilidades que acabas de aprender. Las habilidades de un tomo o una misión aparecen un momento después de aprenderlas. Arrastra una desde la ventana a tus barras."
