L["At a profession trainer who teaches any of your favourite recipes that you can learn now (star one before its name, or right-click it in the list), a window beside the trainer's lists them with their cost: Learn one, or Learn All."] = "Con un instructor de profesión que enseña alguna de tus recetas favoritas que puedes aprender ahora (marca una con la estrella antes de su nombre o haz clic derecho en ella en la lista), una ventana junto al instructor las enumera con su costo: aprende una o Aprender todo."
L["At a vendor who sells them, tops your class reagents and ammo up to what you carry, and prints what it spent. Off by default: it spends gold for you."] = "Con un vendedor que los vende, repone los componentes de clase y la munición hasta lo que llevas, y muestra lo que gastó. Desactivado de forma predeterminada: gasta oro por ti."
