L["At login, names any of your characters with mail that expires within three days. It knows each character's mail from the last time it opened a mailbox."] = "Al iniciar sesión, nombra a cualquiera de tus personajes con correo que expira en tres días. Conoce el correo de cada personaje de la última vez que abrió un buzón."
L["At the auction house, a window beside it lists the patterns, plans and manuals of your favourite recipes that you have not learned or bought, with what they cost now. Buy finds the cheapest and asks before Accept buys it."] = "En la casa de subastas, una ventana al lado enumera los patrones, diseños y manuales de tus recetas favoritas que no aprendiste ni compraste, con lo que cuestan ahora. Comprar encuentra el más barato y pregunta antes de que Aceptar lo compre."
