L["Crafting several at once (Create All, or Create with a count) shows one bar for the whole batch, drawn like the Flight Timer: the recipe, how many are done and the time left on all of them, in place of the cast bar that fills for every craft. It sits where the Flight Timer is, as nobody crafts in flight: move it in the HUD Editor as the Flight Timer."] = "Fabricar varios a la vez (Crear todo, o Crear con una cantidad) muestra una barra para toda la tanda, dibujada como el Temporizador de vuelo: la receta, cuántos están hechos y el tiempo restante de todos, en lugar de la barra de lanzamiento que se llena por cada fabricación. Se ubica donde está el Temporizador de vuelo, ya que nadie fabrica en vuelo: muévela en el Editor de HUD como el Temporizador de vuelo."
