L["Drag the right edge for width, a line's bottom for height. Wheel: text size (Shift: spacing, Ctrl: lines). Right-click a line for what it shows."] = "Arrastra el borde derecho para el ancho, el borde inferior de una línea para la altura. Rueda: tamaño del texto (Mayús: espaciado, Ctrl: líneas). Clic derecho en una línea para lo que muestra."
L["Drag the right edge for width. Wheel: text size (Shift: height). Click a bonus or the time to show or hide it. Right-click for more."] = "Arrastra el borde derecho para el ancho. Rueda: tamaño del texto (Mayús: altura). Haz clic en una bonificación o el tiempo para mostrarlos u ocultarlos. Clic derecho para más."
L["Drag to make the map bigger or smaller.\nRight-click: back to 100%."] = "Arrastra para agrandar o achicar el mapa.\nClic derecho: volver al 100%."
