L["For paladins, a button per class in your group. Left-click blesses the next member of that class who needs it, missing first, skipping anyone dead or out of range. Right-click a class to choose its blessing or open its player list. Move it in the HUD Editor. The preview edits it: right-click a class for its blessing, click the aura to choose it, wheel for size and Shift-wheel for spacing, drag the gap after the aura, x hides a button and + brings it back."] = "Para paladines, un botón por clase de tu grupo. Clic izquierdo bendice al siguiente miembro de esa clase que lo necesite, primero a quien le falte, omitiendo a los muertos o fuera de alcance. Clic derecho en una clase para elegir su bendición o abrir su lista de jugadores. Muévelo en el Editor de HUD. La vista previa lo edita: clic derecho en una clase para su bendición, clic en el aura para elegirla, rueda para el tamaño y Mayús+rueda para el espaciado, arrastra el espacio después del aura, x oculta un botón y + lo recupera."
L["For Skyborne characters: ley lines (Alliance, for Read Ley Line) or Elemental Convergences (Horde, for Skysight) pinned on the world map. The game does not mark them: the addon knows the ones players have found, and saves each new one you cast your racial on. Other races see no pins."] = "Para personajes Skyborne: líneas Ley (Alianza, para Leer línea Ley) o convergencias elementales (Horda, para Visión cielonata) marcadas en el mapa del mundo. El juego no las marca: el addon conoce las que encontraron los jugadores y guarda cada nueva en la que lanzas tu habilidad racial. Las demás razas no ven marcadores."
L["For your class: imports this set once on a new character, at level 1 with no experience yet."] = "Para tu clase: importa este conjunto una vez en un personaje nuevo, en el nivel 1 sin experiencia aún."
L["For your level"] = "Para tu nivel"
L["Forget %s on %s? It comes back the next time you log in on it with a Mail & Alts option on."] = "¿Olvidar %s en %s? Vuelve la próxima vez que inicies sesión con él con una opción de Correo y alters activada."
