L["How close a book has to be before it pings."] = "Qué tan cerca debe estar un libro para que avise."
L["How early you can press your next spell before the current one finishes, in milliseconds. 100 to 400 suits most: lower is more responsive, higher is more forgiving of latency. Melee around your ping + 100, ranged around your ping + 150."] = "Cuánto antes puedes pulsar tu siguiente hechizo antes de que termine el actual, en milisegundos. De 100 a 400 sirve para la mayoría: más bajo responde mejor, más alto tolera más la latencia. Cuerpo a cuerpo alrededor de tu ping + 100, a distancia alrededor de tu ping + 150."
L["How far along an icon starts to fade, from 0% (at once) to 95% (at the very end)."] = "En qué punto empieza a desvanecerse un ícono, de 0% (de inmediato) a 95% (al final)."
L["How far below your level gear has to be for Old Common Gear."] = "Cuánto por debajo de tu nivel debe estar el equipo para Equipo común antiguo."
L["How Group Inspect shows a party and a raid, with sample players."] = "Cómo muestra Inspección de grupo un grupo y una banda, con jugadores de ejemplo."
L["How little Camp Benefits time counts as needing a refresh."] = "Con cuán poco tiempo de Beneficios de campamento se considera que necesitan renovarse."
L["How long an interrupted cast stays up. 0 hides it at once."] = "Cuánto tiempo se muestra un lanzamiento interrumpido. 0 lo oculta de inmediato."
L["How long before the effect runs out it shows again."] = "Cuánto antes de que termine el efecto vuelve a mostrarse."
L["How long each line stays before it fades."] = "Cuánto tiempo se queda cada línea antes de desvanecerse."
L["How long it takes to get there at your speed."] = "Cuánto tardas en llegar a tu velocidad."
