L["How long the fight lasted, in chat when it ends."] = "Cuánto duró el combate, en el chat al terminar."
L["How long the next level takes at your current rate."] = "Cuánto tarda el siguiente nivel a tu ritmo actual."
L["How long this session has run."] = "Cuánto lleva esta sesión."
L["How many crafts Add to List adds the materials for."] = "Para cuántas fabricaciones agrega materiales Agregar a la lista."
