L["Invites the crafter to your group, with a whisper saying it is for crafts from their profession. Once they are in your party, Ask sends the order in party chat instead of whispering it. Greyed out once they are in your group, or while you are in a group and not its leader or an assistant."] = "Invita al artesano a tu grupo, con un susurro que dice que es para fabricaciones de su profesión. Una vez en tu grupo, Preguntar envía el pedido por el chat de grupo en lugar de susurrarlo. Se atenúa cuando ya está en tu grupo, o mientras estás en un grupo y no eres su líder ni asistente."
L["Invites your target. Works in combat."] = "Invita a tu objetivo. Funciona en combate."
