L["Open World"] = "Mundo abierto"
L["opens "] = "abre "
L["Opens another player's profession link in this window, to order crafts from them. Choose a recipe, set how many crafts, tick the materials you bring (or type how many), and Add to Order. The order on the right has a suggested tip per craft that you can change; Ask sends the crafter one message per craft with the amount, your materials and the tip: in party chat when they are in your party, else as a whisper. Prices and the tip need an auction house scan."] = "Abre en esta ventana el enlace de profesión de otro jugador, para pedirle fabricaciones. Elige una receta, ajusta cuántas fabricaciones, marca los materiales que aportas (o escribe cuántos) y Agregar al orden. El pedido de la derecha tiene una propina sugerida por fabricación que puedes cambiar; Preguntar le envía al artesano un mensaje por fabricación con la cantidad, tus materiales y la propina: por el chat de grupo si está en tu grupo, si no, como susurro. Los precios y la propina requieren un escaneo de la casa de subastas."
L["Opens its settings and leaves the HUD Editor."] = "Abre su configuración y sale del Editor de HUD."
L["Opens the Aim Trainer now, out of combat."] = "Abre ahora el Entrenador de puntería, fuera de combate."
L["Opens the AuraBuffs window, where you add each item by its item ID and buff spell ID."] = "Abre la ventana de AuraBuffs, donde agregas cada objeto por su ID de objeto y su ID de hechizo de beneficio."
L["Opens the Consumable Bar's settings."] = "Abre la configuración de la Barra de consumibles."
L["Opens the copy card on a sample spell. Select the ID or link, then Ctrl+C."] = "Abre la tarjeta de copia con un hechizo de ejemplo. Selecciona el ID o el enlace y luego Ctrl+C."
L["Opens the Dungeon Journal's Quest Tracker settings."] = "Abre la configuración del Rastreador de misiones del Diario de calabozos."
L["Opens the HUD Editor: click another Naowh Forever element for the bar to move with."] = "Abre el Editor de HUD: haz clic en otro elemento de Naowh Forever para que la barra se mueva con él."
L["Opens the Library Books tracker's settings."] = "Abre la configuración del rastreador de Libros de la biblioteca."
L["Opens the planner on its Builds tab."] = "Abre el planificador en su pestaña Builds."
L["Opens the quest tracker out in the world, on the dungeon your quests are for."] = "Abre el rastreador de misiones en el mundo, en el calabozo para el que son tus misiones."
L["Opens the quest tracker when you enter a dungeon with quests for you."] = "Abre el rastreador de misiones al entrar en un calabozo con misiones para ti."
L["Opens the quiz now, or closes it."] = "Abre el cuestionario ahora, o lo cierra."
L["Opens the Run Timer settings."] = "Abre la configuración del Temporizador de recorrido."
L["Opens the Sleeping Bag tracker's settings."] = "Abre la configuración del rastreador del Saco de dormir."
L["Opens the Stat Weights window: each stat's worth to your spec, and your best upgrades by them."] = "Abre la ventana de Pesos de estadísticas: lo que vale cada estadística para tu especialización y tus mejores mejoras según ellos."
L["Opens the window now, out of combat."] = "Abre la ventana ahora, fuera de combate."
