L["Plays once each time your health drops below the threshold. If the game hides your health from addons mid-fight, it only plays out of combat."] = "Suena una vez cada vez que tu salud baja del umbral. Si el juego oculta tu salud a los addons en pleno combate, solo suena fuera de combate."
