L["Put back every setting this page has changed?"] = "¿Restaurar todos los ajustes que cambió esta página?"
L["put down what you are holding first."] = "primero suelta lo que tienes en la mano."
L["Put every %s weight back to the defaults?"] = "¿Restablecer todos los pesos de %s a los predeterminados?"
L["Put every setting back to how it was before the onboarding?"] = "¿Devolver todos los ajustes a como estaban antes de la introducción?"
L["Put every setting in this profile back to its default."] = "Devuelve todos los ajustes de este perfil a su valor predeterminado."
L["Put on in cities and inns, and taken off again when you leave."] = "Se pone en ciudades y posadas, y se quita al salir."
L["Put on while you ride, and the set you had on goes back when you dismount."] = "Se pone mientras montas, y el conjunto que tenías vuelve al desmontar."
L["Put the XP Bar colors back to their defaults?"] = "¿Restablecer los colores de la barra de EXP a los predeterminados?"
