L["Puts the text just past the icon's edge."] = "Pone el texto justo fuera del borde del ícono."
L["Puts this recipe on the order on the right, with the number of crafts and the materials you bring. Changes made here after adding it change the order too. Up to %d recipes per order."] = "Pone esta receta en el pedido de la derecha, con la cantidad de fabricaciones y los materiales que aportas. Los cambios hechos aquí después de agregarla también cambian el pedido. Hasta %d recetas por pedido."
L["Puts this set on. In combat, it goes on when the fight ends."] = "Te pone este conjunto. En combate, se pone al terminar el combate."
L["Puts your settings to one of Naowh's setups, or walks you through them again."] = "Ajusta tu configuración a una de las de Naowh, o te guía por ellas otra vez."
