L["Shows a dungeon's bosses and loot beside the world map while you are inside."] = "Muestra los jefes y el botín de un calabozo junto al mapa del mundo mientras estás dentro."
L["Shows a healing item's icon the moment your health drops below the threshold, in combat too: the game shows and hides it itself. Move it in the HUD Editor."] = "Muestra el ícono de un objeto de sanación en el momento en que tu salud baja del umbral, también en combate: el juego lo muestra y oculta por sí mismo. Muévelo en el Editor de HUD."
L["Shows a sample spell's tooltip with the line as your settings draw it."] = "Muestra la descripción emergente de un hechizo de ejemplo con la línea tal como la dibuja tu configuración."
L["Shows a zone's level range when you hover it on the world map."] = "Muestra el rango de niveles de una zona al pasar el cursor sobre ella en el mapa del mundo."
L["Shows an icon on screen while you know Find Herbs, Find Minerals or Find Fish but are tracking none of them. Click it to start tracking: left-click for the first, right-click for the second, middle-click for the third. Hover it to see which is which. Hidden in combat. Move it in the HUD Editor."] = "Muestra un ícono en pantalla mientras conoces Encontrar hierbas, Encontrar minerales o Buscar pescado pero no rastreas ninguno. Haz clic para empezar a rastrear: clic izquierdo para el primero, clic derecho para el segundo, clic central para el tercero. Pasa el cursor para ver cuál es cuál. Oculto en combate. Muévelo en el Editor de HUD."
L["Shows each Sleeping Bag step, with how to reach the next one and a waypoint."] = "Muestra cada paso del Saco de dormir, con cómo llegar al siguiente y un punto de ruta."
L["Shows every bonus again; click one on the preview to hide it."] = "Vuelve a mostrar todas las bonificaciones; haz clic en una de la vista previa para ocultarla."
L["Shows how many of each you carry."] = "Muestra cuántos llevas de cada uno."
L["Shows if you're ahead of or behind your other characters, and colors past levels by it."] = "Muestra si vas adelante o atrás de tus otros personajes, y colorea los niveles pasados según eso."
L["Shows it again a little before its effect runs out."] = "Vuelve a mostrarlo un poco antes de que termine su efecto."
L["Shows only part of the raid."] = "Muestra solo una parte de la banda."
L["Shows or hides the list of every element."] = "Muestra u oculta la lista de todos los elementos."
L["Shows the factions earned where you are beside the world map."] = "Muestra junto al mapa del mundo las facciones que se obtienen donde estás."
L["Shows the key that uses each button."] = "Muestra la tecla que usa cada botón."
L["Shows the meter with sample bars where it sits on your screen, for ten seconds. Out of combat only."] = "Muestra el medidor con barras de ejemplo donde está en tu pantalla, durante diez segundos. Solo fuera de combate."
L["Shows the other tank's debuffs beside their health bar, in combat too: tank-buster stacks, boss debuffs and anything you can dispel."] = "Muestra los perjuicios del otro tanque junto a su barra de salud, también en combate: acumulaciones de golpes de jefe, perjuicios de jefe y todo lo que puedas disipar."
L["Shows the parts of the world map you have not explored yet, darkened."] = "Muestra oscurecidas las partes del mapa del mundo que aún no exploraste."
L["Shows the row only once your bags are this full. 0 shows it all the time."] = "Muestra la fila solo cuando tus bolsas están así de llenas. 0 la muestra siempre."
L["Shows the Sleeping Bag steps still to do on your map; click one for a waypoint."] = "Muestra en tu mapa los pasos del Saco de dormir que faltan; haz clic en uno para un punto de ruta."
L["Shows the warning with its sound, about your target if you can attack it."] = "Muestra el aviso con su sonido, sobre tu objetivo si puedes atacarlo."
L["Shows this bonus on the bar: %s."] = "Muestra esta bonificación en la barra: %s."
L["Shows this recipe's reagents in your objective tracker, with how many you have of each."] = "Muestra los componentes de esta receta en tu rastreador de objetivos, con cuántos tienes de cada uno."
L["Shows this visit's time, coins, and experience."] = "Muestra el tiempo, las monedas y la experiencia de esta visita."
L["Shows up once you take the talent"] = "Aparece cuando tomas el talento"
L["Shows who Naowh, the developers, the moderators and our Legendary and Epic patrons are: a badge by their name in chat, a line on their tooltip and, if you want it, a banner when one of them joins your group."] = "Muestra quiénes son Naowh, los desarrolladores, los moderadores y nuestros mecenas legendarios y épicos: una insignia junto a su nombre en el chat, una línea en su descripción emergente y, si quieres, un aviso cuando uno de ellos se une a tu grupo."
L["Shows your BiS stars to players who inspect you with Naowh Forever."] = "Muestra tus estrellas BiS a los jugadores que te inspeccionan con Naowh Forever."
L["Shows your note and tag on a player's tooltip."] = "Muestra tu nota y etiqueta en la descripción emergente de un jugador."
L["Shows your other characters' visits."] = "Muestra las visitas de tus otros personajes."
