L["The arrows or shot in your ammo slot."] = "Las flechas o balas de tu casilla de munición."
L["The auction house gave no final price."] = "La casa de subastas no dio un precio final."
L["The auction house has no price for it right now."] = "La casa de subastas no tiene precio para esto ahora."
L["The auction house returned no listings. Try again in a moment."] = "La casa de subastas no devolvió publicaciones. Vuelve a intentarlo en un momento."
L["The AuraBuffs window: the consumables to watch."] = "La ventana de AuraBuffs: los consumibles a vigilar."
L["The bar and the FPS / MS readout fade to Faded Opacity until you hover them. Their buttons still click while faded."] = "La barra y los FPS / MS se desvanecen a la Opacidad desvanecida hasta que pasas el cursor sobre ellos. Sus botones siguen respondiendo aunque estén desvanecidos."
L["The bar as it shows outside a fight."] = "La barra tal como se ve fuera de combate."
L["The bar as it sits on your screen."] = "La barra tal como está en tu pantalla."
L["The best scores of the players you have met, in this mode."] = "Las mejores puntuaciones de los jugadores que conociste, en este modo."
L["The BiS List's own window, and its Stat Weights window."] = "La ventana propia de la lista BiS, y su ventana de Pesos de estadísticas."
L["The BiS rankings behind the BiS List."] = "Las clasificaciones BiS detrás de la lista BiS."
L["The book count is what players report; not confirmed yet."] = "El conteo de libros es lo que reportan los jugadores; aún no está confirmado."
L["The boss or place it comes from."] = "El jefe o el lugar de donde viene."
L["The buffs show while you hover the icon."] = "Los beneficios se muestran al pasar el cursor sobre el ícono."
L["The build's next talent cannot be taken now: your talents are not the build's."] = "El siguiente talento de la build no se puede tomar ahora: tus talentos no son los de la build."
L["The calendar cannot be opened from the Top Bar with a gamepad."] = "El calendario no se puede abrir desde la Barra superior con un mando."
L["The card at the end of a round."] = "La tarjeta al final de una ronda."
L["The cheapest items in your bags as a row of icons, cheapest first. Ctrl-click an icon to delete it, or click it to sell it while a vendor is open. Middle-click to ignore an item. Move it in the HUD Editor."] = "Los objetos más baratos de tus bolsas como una fila de íconos, el más barato primero. Ctrl+clic en un ícono para eliminarlo, o clic para venderlo mientras hay un vendedor abierto. Clic central para ignorar un objeto. Muévela en el Editor de HUD."
L["The class's name, or its class icon, which fits however small the buttons are."] = "El nombre de la clase, o su ícono de clase, que cabe sin importar lo pequeños que sean los botones."
L["The color of the line on the tooltip."] = "El color de la línea en la descripción emergente."
L["The Consumable Bar will ask about those items again."] = "La Barra de consumibles volverá a preguntar por esos objetos."
L["The consumables your reminders watch"] = "Los consumibles que vigilan tus recordatorios"
L["The consumables your reminders watch."] = "Los consumibles que vigilan tus recordatorios."
L["The Cozy Sleeping Bag's hidden quest chain, step by step."] = "La cadena de misiones oculta del Saco de dormir acogedor, paso a paso."
L["The crowd control on your target; pick which in the Crowd Control card below."] = "El control de masas sobre tu objetivo; elige cuál en la tarjeta Control de masas de abajo."
L["The Ctrl-click line, and Click to sell while a vendor is open."] = "La línea de Ctrl+clic, y Clic para vender mientras hay un vendedor abierto."
L["The cursor left still."] = "El cursor quieto."
L["The debuffs on your target you pick in the Debuffs card below, like Mortal Strike."] = "Los perjuicios sobre tu objetivo que elijas en la tarjeta Perjuicios de abajo, como Golpe mortal."
L["The default is %s."] = "El predeterminado es %s."
L["The default is %s. Click to put it back."] = "El predeterminado es %s. Haz clic para restablecerlo."
L["The Disenchant window cannot open in combat."] = "La ventana de desencantar no se puede abrir en combate."
L["The Dungeon Quest Tracker's window."] = "La ventana del Rastreador de misiones de calabozo."
L["The dungeons on whose ground the list shows. Contested ones and the raids are always listed. Also the switch beside the Journal's search."] = "Los calabozos en cuyo territorio se muestra la lista. Los que están en territorio en disputa y las bandas siempre se enumeran. También el interruptor junto a la búsqueda del Diario."
L["The Edit Items window."] = "La ventana Editar objetos."
L["The extra gap between your aura and Righteous Fury and the class buttons."] = "El espacio extra entre tu aura y Furia recta y los botones de clase."
L["The fastest way to any waypoint."] = "El camino más rápido a cualquier punto de ruta."
L["The first %d of %d; type more to narrow it down."] = "Los primeros %d de %d; escribe más para acotar."
L["The first time someone speaks, ask their Naowh Forever for their zone with a hidden addon whisper. Players without it never see the question."] = "La primera vez que alguien habla, pregunta su zona a su Naowh Forever con un susurro oculto del addon. Los jugadores sin él nunca ven la pregunta."
L["The flight time to each destination when you hover it on the flight master's map."] = "El tiempo de vuelo a cada destino al pasar el cursor sobre él en el mapa del maestro de vuelo."
L["The font for damage and healing numbers, over enemies and over your character. Off leaves the game's own font alone."] = "La fuente de los números de daño y sanación, sobre enemigos y sobre tu personaje. Desactivado deja la fuente del juego como está."
L["The font for the rest of the game: menus, chat, tooltips and names. Off leaves the game's own fonts alone."] = "La fuente del resto del juego: menús, chat, descripciones emergentes y nombres. Desactivado deja las fuentes del juego como están."
L["The font for this addon's windows and HUD. Font settings on a feature use it unless they pick their own. Saved for this computer.|n|nTakes effect after a /reload."] = "La fuente de las ventanas y el HUD de este addon. Los ajustes de fuente de una función la usan a menos que elijan la suya. Guardado para esta computadora.|n|nSe aplica después de un /reload."
L["The FPS / MS readout and the online counts on the buttons."] = "Los FPS / MS y los contadores de conectados en los botones."
L["The FPS / MS readout stays up."] = "Los FPS / MS siguen visibles."
L["The game does not name this fight yet: its kills count once the raid opens."] = "El juego aún no nombra este combate: sus muertes cuentan cuando abra la banda."
L["The game has no PvP rank for you yet. It shows once the season has started."] = "El juego aún no tiene un rango JcJ para ti. Se muestra cuando empiece la temporada."
L["The game has no route for %s, and its quest giver's spot is not known."] = "El juego no tiene ruta para %s, y no se conoce el lugar de quien da la misión."
L["The game is not passing addon messages right now (in an encounter): ask again after it."] = "El juego no está pasando mensajes de addons ahora (en un encuentro): vuelve a preguntar después."
L["The game lists no rank rewards for this season yet."] = "El juego aún no enumera recompensas de rango para esta temporada."
L["The game would not disenchant this (skill too low?). Skipped until you reload."] = "El juego no quiso desencantar esto (¿habilidad demasiado baja?). Se omite hasta que recargues."
L["The game's own alert sounds first, then the addon's. Each plays as you pick it."] = "Primero los sonidos de alerta propios del juego y luego los del addon. Cada uno suena al elegirlo."
L["The game's own look, in gold and bronze."] = "El aspecto propio del juego, en oro y bronce."
L["The gap between the two."] = "El espacio entre los dos."
L["The gap between two buttons."] = "El espacio entre dos botones."
L["The Gear Sets window, with every set and what you can do with it."] = "La ventana de Conjuntos de equipo, con cada conjunto y lo que puedes hacer con él."
L["The group can be disbanded once the fight is over."] = "El grupo se puede disolver cuando termine el combate."
L["The group's paladins and the blessing each gives every class."] = "Los paladines del grupo y la bendición que cada uno da a cada clase."
L["The guild name under a player's name."] = "El nombre de la hermandad bajo el nombre de un jugador."
L["The highest rank this season"] = "El rango más alto de esta temporada"
L["The icon grows and shrinks with it."] = "El ícono crece y se encoge con él."
L["The inspect window in the BiS List's look, with their score, gear check, talents and history."] = "La ventana de inspección con el aspecto de la lista BiS, con su puntuación, revisión de equipo, talentos e historial."
L["The item's cooldown sweeps over its icon."] = "El tiempo de reutilización del objeto barre su ícono."
L["The item's quality"] = "La calidad del objeto"
L["The item, your star and what happened, on screen for a while."] = "El objeto, tu estrella y lo que pasó, en pantalla por un rato."
L["The items the Buffs & Consumables reminders watch."] = "Los objetos que vigilan los recordatorios de Beneficios y consumibles."
L["The Journal beside the world map: bosses and loot in dungeons, factions outside."] = "El Diario junto al mapa del mundo: jefes y botín en calabozos, facciones afuera."
L["The Journal's own window."] = "La ventana propia del Diario."
L["The key that changes Accept Quests, Hand In Quests, Pick Quests From NPCs and sharing."] = "La tecla que cambia Aceptar misiones, Entregar misiones, Elegir misiones de PNJ y compartir."
L["The key that changes Auto Gossip for that NPC."] = "La tecla que cambia el diálogo automático para ese PNJ."
L["The key that opens the BiS List."] = "La tecla que abre la lista BiS."
L["The key that opens the Journal."] = "La tecla que abre el Diario."
L["The key that opens the Quest List window."] = "La tecla que abre la ventana de Lista de misiones."
L["The last %ds, scrolling %s%s"] = "Los últimos %d s, desplazándose %s%s"
L["The last fight's time stays on screen until the next one starts."] = "El tiempo del último combate se queda en pantalla hasta que empiece el siguiente."
L["The last part of each melee swing, shaded."] = "La última parte de cada golpe cuerpo a cuerpo, sombreada."
L["the last profile cannot be deleted"] = "el último perfil no se puede eliminar"
L["The last profile cannot be deleted."] = "El último perfil no se puede eliminar."
L["The latest %d kills. First counted: %s."] = "Las últimas %d muertes. Primera contada: %s."
L["The latest %d. First counted: %s."] = "Los últimos %d. Primero contado: %s."
L["The leader's zone on each Group Finder listing, and every member's zone when you hover it."] = "La zona del líder en cada anuncio del Buscador de grupos, y la zona de cada miembro al pasar el cursor."
L["The level you are on as it runs, then completed levels, newest first."] = "El nivel en el que estás mientras avanza, y luego los niveles completados, el más reciente primero."
L["The line round the bar."] = "La línea alrededor de la barra."
L["The list this character uses."] = "La lista que usa este personaje."
L["The longest a buff can last to show; longer ones like Arcane Intellect stay hidden."] = "Lo máximo que puede durar un beneficio para mostrarse; los más largos como Intelecto Arcano se quedan ocultos."
L["The macros the addon writes and keeps up to date for you, out of combat. Switch one on here, or take it to your bars from Smart Macros in Naowh's Forge."] = "Las macros que el addon escribe y mantiene al día por ti, fuera de combate. Activa una aquí, o llévala a tus barras desde Macros inteligentes en la Forja de Naowh."
L["The macros you saved to the Forge's Library."] = "Las macros que guardaste en la biblioteca de la Forja."
L["The Man. The King."] = "El hombre. El rey."
L["The map's window, the Journal beside the world map and Boss Loot at Cursor."] = "La ventana del mapa, el Diario junto al mapa del mundo y Botín del jefe en el cursor."
L["The marks on the game's own character panel, as it looks (or EllesmereUI's), without the Naowh Character Panel. With it on, its slots have them already."] = "Las marcas en el panel de personaje propio del juego, tal como se ve (o el de EllesmereUI), sin el panel de personaje de Naowh. Con este activado, sus casillas ya las tienen."
L["The Middle-click line."] = "La línea de clic central."
L["The most recent completed levels."] = "Los niveles completados más recientes."
L["the name is empty"] = "el nombre está vacío"
L["The name on it, and the community it is made for."] = "El nombre que lleva, y la comunidad para la que está hecho."
L["The Naowh Forever button on the minimap. The addon compartment entry and /naowh open this window either way."] = "El botón de Naowh Forever en el minimapa. La entrada del compartimento de addons y /naowh abren esta ventana de todos modos."
L["The Naowh Forever N next to the name of Naowh, the developers, the moderators and our Legendary and Epic patrons in chat."] = "La N de Naowh Forever junto al nombre de Naowh, los desarrolladores, los moderadores y nuestros mecenas legendarios y épicos en el chat."
L["The newest line stays at the anchor; older lines stack in this direction."] = "La línea más nueva se queda en el ancla; las más antiguas se apilan en esta dirección."
L["The next one frees in "] = "La siguiente se libera en "
L["the next rank of %s (cap %d)"] = "el siguiente rango de %s (límite %d)"
L["The number on each icon counts your bank as well as your bags."] = "El número de cada ícono cuenta tu banco además de tus bolsas."
L["The order the points are taken in"] = "El orden en que se toman los puntos"
L["the pattern"] = "el patrón"
L["The people and projects behind Naowh Forever."] = "Las personas y proyectos detrás de Naowh Forever."
L["The picked boss's loot and abilities, under the map."] = "El botín y las habilidades del jefe elegido, bajo el mapa."
L["The planner's own window, and a mini bar to leave up while you level."] = "La ventana propia del planificador, y una minibarra para dejar visible mientras subes de nivel."
L["The player list opens after combat."] = "La lista de jugadores se abre después del combate."
L["The player's guild rank beside their guild name."] = "El rango de hermandad del jugador junto al nombre de su hermandad."
L["The point of the bar that attaches."] = "El punto de la barra que se adjunta."
L["The point of the frame it attaches to."] = "El punto del marco al que se adjunta."
L["The purchase failed."] = "La compra falló."
L["The purchase failed; the price may have changed."] = "La compra falló; puede que el precio haya cambiado."
L["The purchase failed; the price may have changed.|r"] = "La compra falló; puede que el precio haya cambiado.|r"
L["The quest tracker, and sharing dungeon quests with your group."] = "El rastreador de misiones, y compartir misiones de calabozo con tu grupo."
L["The quests that reward a pick you do not have yet."] = "Las misiones que recompensan una elección que aún no tienes."
L["The quiz opens when you sit down at a campfire and closes when you stand up."] = "El cuestionario se abre cuando te sientas en una fogata y se cierra cuando te levantas."
L["The raid marker Mark Focus puts on your focus."] = "La marca de banda que Marcar foco pone en tu foco."
L["the rank before"] = "el rango anterior"
L["The ready ring shows with GCD Sweep on."] = "El anillo de listo se muestra con Barrido del TRG activado."
L["The reagents your known spells use, such as Arcane Powder, candles, seeds, Symbols of Kings and Flash Powder, matched to the highest rank you know."] = "Los componentes que usan tus hechizos conocidos, como Polvo arcano, velas, semillas, Símbolos de reyes y Polvo destellante, según el rango más alto que conoces."
L["The red time left blinks, to catch your eye."] = "El tiempo restante en rojo parpadea para llamar tu atención."
L["The same required-level filter applies to every stack, not each item separately."] = "El mismo filtro de nivel requerido se aplica a todos los montones, no a cada objeto por separado."
L["The same sets as the character sheet's: equip, save, rename or delete them in the Gear Sets window."] = "Los mismos conjuntos que los de la hoja de personaje: equípalos, guárdalos, renómbralos o elimínalos en la ventana de Conjuntos de equipo."
L["The same with a Greater Blessing, for a class that shares one blessing, while you carry Symbols of Kings."] = "Lo mismo con una Bendición superior, para una clase que comparte una bendición, mientras llevas Símbolos de reyes."
L["The seconds left when the time turns red; it turns yellow at twice that."] = "Los segundos restantes cuando el tiempo se vuelve rojo; se vuelve amarillo al doble de eso."
L["The serializer libraries are missing from this build."] = "Faltan las bibliotecas de serialización en esta versión."
L["The shape of Naowh's arrow."] = "La forma de la flecha de Naowh."
L["The share of what the items sell for that the suggested tip adds on top of paying back the crafter's own materials. At least 1s unless set to 0."] = "La parte de lo que valen los objetos que la propina sugerida agrega, además de reponer los materiales propios del artesano. Al menos 1p a menos que se ponga en 0."
L["The shortest time between two thanks to the same player."] = "El tiempo mínimo entre dos agradecimientos al mismo jugador."
L["The Slot"] = "La casilla"
L["The slot it is for."] = "La casilla para la que es."
L["The slots and stats only"] = "Solo las casillas y estadísticas"
L["The space between Naowh's arrow and the text under it."] = "El espacio entre la flecha de Naowh y el texto debajo."
L["The spec your gear is weighed for. Automatic follows your talents: the tree with the most points (a druid's Feral is weighed for damage; pick Feral Tank for a bear)."] = "La especialización para la que se valora tu equipo. Automático sigue tus talentos: el árbol con más puntos (el Feral de un druida se valora para daño; elige Tanque feral para un oso)."
L["The spot ahead of you, 312 yards away."] = "El lugar delante de ti, a 312 m."
L["The spot off to your right."] = "El lugar a tu derecha."
L["The stat weights each spec starts with."] = "Los pesos de estadísticas con los que empieza cada especialización."
L["The stealthed text while you are in stealth, as well as the reminder when you are not."] = "El texto de sigilo mientras estás en sigilo, además del recordatorio cuando no lo estás."
L["The step and distance text under RestedXP's waypoint arrow."] = "El texto de paso y distancia bajo la flecha de punto de ruta de RestedXP."
L["The string is damaged: copy it again in full."] = "La cadena está dañada: vuelve a copiarla completa."
L["The suggested tip pays back the crafter's materials plus %d%% of what the items sell for (of all the materials, for a recipe that makes no item), rounded, at least 1s. Set a tip of your own in the order list on the right. Change the share in the Professions settings."] = "La propina sugerida repone los materiales del artesano más el %d%% de lo que valen los objetos (de todos los materiales, para una receta que no fabrica ningún objeto), redondeada, al menos 1p. Pon tu propia propina en la lista de pedidos de la derecha. Cambia la proporción en la configuración de Profesiones."
L["The swing timer needs WoW: Forever's own swing event."] = "El temporizador de golpes necesita el evento de golpe propio de WoW: Forever."
L["The tag in the speaker's class color. Off, it is grey."] = "La etiqueta con el color de clase de quien habla. Desactivado, es gris."
L["the talent above it"] = "el talento de arriba"
L["The talent builds you saved in the Training Planner."] = "Las builds de talentos que guardaste en el Planificador de entrenamiento."
L["The Team"] = "El equipo"
L["The text in the theme's accent color instead of gold."] = "El texto en el color de acento del tema en lugar de dorado."
L["The theme RestedXP uses: its own, or one of the Naowh themes."] = "El tema que usa RestedXP: el suyo o uno de los temas de Naowh."
L["The time between the two sides. Click it for the calendar (not with a gamepad)."] = "La hora entre los dos lados. Haz clic para el calendario (no con mando)."
L["The time left turns yellow, then red near the end, so you see crowd control about to break."] = "El tiempo restante se vuelve amarillo y luego rojo cerca del final, para que veas cuándo está por romperse el control de masas."
L["The time left, turning yellow, then red, as the camp runs down."] = "El tiempo restante, que se vuelve amarillo y luego rojo, a medida que se agota el campamento."
L["The tint on every button's icon: Naowh's own and any addon's."] = "El tinte del ícono de cada botón: los de Naowh y los de cualquier addon."
L["The Training Planner's help while you level: a toast when you level up with spells to train, and a panel beside your class trainer."] = "La ayuda del Planificador de entrenamiento mientras subes de nivel: un aviso al subir de nivel con hechizos para entrenar, y un panel junto a tu instructor de clase."
L["The unit frame the bar is attached to, or UIParent for the screen."] = "El marco de unidad al que está adjunta la barra, o UIParent para la pantalla."
L["The weights"] = "Los pesos"
L["The weights for %s."] = "Los pesos para %s."
L["The window's border fades with it."] = "El borde de la ventana se desvanece con ella."
L["The word itself."] = "La palabra en sí."
L["The XP of completed quests, and their text."] = "La EXP de las misiones completadas, y su texto."
L["The XP of quests still in progress, as a faded segment after the completed ones."] = "La EXP de las misiones aún en curso, como un segmento desvanecido después de las completadas."
L["The XP of quests still in progress. By default the completed quests color, faded."] = "La EXP de las misiones aún en curso. De forma predeterminada, el color de misiones completadas, desvanecido."
L["The zone of whoever speaks in a chat channel, guild chat or a whisper, in front of their message. The game never says where a stranger is, so a player is tagged once they are in the Group Finder, your guild, your friends or your group, came up in a /who, or answered from their own copy of Naowh Forever. Their first message may come through untagged."] = "La zona de quien habla en un canal de chat, el chat de hermandad o un susurro, delante de su mensaje. El juego nunca dice dónde está un desconocido, así que un jugador queda etiquetado cuando está en el Buscador de grupos, tu hermandad, tus amigos o tu grupo, apareció en un /who o respondió desde su propia copia de Naowh Forever. Su primer mensaje puede llegar sin etiqueta."
L["Their BiS"] = "Su BiS"
L["THEIR GEAR"] = "SU EQUIPO"
L["Their gear, talents and history"] = "Su equipo, talentos e historial"
L["their materials + %d%%"] = "sus materiales + %d%%"
L["Their materials:"] = "Sus materiales:"
L["Their Naowh Score at the top of the panel, with yours under it."] = "Su Naowh Score arriba del panel, con el tuyo debajo."
L["Their supporter badge in the window's corner, if they have one."] = "Su insignia de colaborador en la esquina de la ventana, si tiene una."
