L["Your BiS"] = "Tu BiS"
L["your BiS"] = "tu BiS"
L["Your BiS in your bags or bank: put it on."] = "Tu BiS en tus bolsas o banco: póntelo."
L["Your BiS list is empty"] = "Tu lista BiS está vacía"
L["Your BiS list now keeps a ranked list per slot. These did not fit: "] = "Tu lista BiS ahora guarda una lista clasificada por casilla. Estos no cupieron: "
L["Your BiS List's slot marks on the items in your bags: item level, your BiS's star, Forever's mark and the green arrow on an upgrade. In the game's bags or EllesmereUI's."] = "Las marcas de casilla de la lista BiS en los objetos de tus bolsas: nivel de objeto, la estrella de tu BiS, la marca de Forever y la flecha verde en una mejora. En las bolsas del juego o las de EllesmereUI."
L["Your BiS lists, for every class."] = "Tus listas BiS, para todas las clases."
L["Your BiS only"] = "Solo tu BiS"
L["Your BiS you do not have yet: where to go next."] = "Tu BiS que aún no tienes: a dónde ir después."
L["Your BiS's star on a slot, and Forever's mark on what is new in Forever."] = "La estrella de tu BiS en una casilla, y la marca de Forever en lo que es nuevo en Forever."
L["Your BiS, your second pick, and so on."] = "Tu BiS, tu segunda elección, y así sucesivamente."
L["Your buttons and a clock along the top."] = "Tus botones y un reloj a lo largo de la parte superior."
L["Your buttons on either side of an optional clock, with FPS and latency underneath."] = "Tus botones a cada lado de un reloj opcional, con FPS y latencia debajo."
L["Your buttons on either side of an optional clock, with FPS and latency underneath. Arrange the buttons in the preview: drag one to move it, its x removes it, a side's + adds one. Move the bar in the HUD Editor."] = "Tus botones a cada lado de un reloj opcional, con FPS y latencia debajo. Ordena los botones en la vista previa: arrastra uno para moverlo, su x lo quita y el + de un lado agrega uno. Mueve la barra en el Editor de HUD."
L["Your camp's bonuses and time left on screen, and a reminder when Camp Benefits runs out."] = "Las bonificaciones y el tiempo restante de tu campamento en pantalla, y un recordatorio cuando se acaban los Beneficios de campamento."
L["Your camp's bonuses by the icon, always or while you hover it."] = "Las bonificaciones de tu campamento junto al ícono, siempre o al pasar el cursor."
L["Your cap is %d.\nFirst do the quest %s%s|r (%sskill %d):"] = "Tu límite es %d.\nPrimero haz la misión %s%s|r (%shabilidad %d):"
L["Your cap is %d.\nFirst read %s (needs skill %d):"] = "Tu límite es %d.\nPrimero lee %s (requiere habilidad %d):"
L["Your cap is %d.\nFirst train %s (%s, needs skill %d):"] = "Tu límite es %d.\nPrimero entrena %s (%s, requiere habilidad %d):"
L["Your cast ends before the swing comes due."] = "Tu lanzamiento termina antes de que llegue el golpe."
L["Your cast will still be going as the swing comes due."] = "Tu lanzamiento seguirá en curso al llegar el golpe."
L["Your casts and channels swept around the ring too."] = "Tus lanzamientos y canalizaciones también barridos alrededor del anillo."
L["Your character panel (C) in the BiS List's look: each slot with its marks, your stats for your spec, and your Naowh Score under your level. The game keeps the panel and everything it does. With EllesmereUI, turning this on turns its character panel off, and off turns it back on, after a reload."] = "Tu panel de personaje (C) con el aspecto de la lista BiS: cada casilla con sus marcas, tus estadísticas para tu especialización y tu Naowh Score bajo tu nivel. El juego conserva el panel y todo lo que hace. Con EllesmereUI, activar esto desactiva su panel de personaje, y desactivarlo lo vuelve a activar, después de recargar."
L["Your Characters"] = "Tus personajes"
L["Your characters at level %d"] = "Tus personajes en el nivel %d"
