L["Your characters on this realm and faction, remembered across your account: what they hold on item tooltips, and help at the mailbox."] = "Tus personajes de este reino y facción, recordados en toda tu cuenta: lo que tienen en las descripciones emergentes de objetos, y ayuda en el buzón."
L["Your Chat"] = "Tu chat"
L["Your chat only"] = "Solo tu chat"
