L["Your equipment sets, the same ones the character sheet keeps."] = "Tus conjuntos de equipo, los mismos que guarda la hoja de personaje."
L["Your experience per hour on a small card, with time to level, played time, session length and recent level times. Hidden at max level. Hover it for Start, Pause and Reset (also /naowh xp start, pause or reset). Move it in the HUD Editor."] = "Tu experiencia por hora en una tarjeta pequeña, con tiempo para subir de nivel, tiempo jugado, duración de la sesión y tiempos de niveles recientes. Oculta en el nivel máximo. Pasa el cursor para Iniciar, Pausar y Restablecer (también /naowh xp start, pause o reset). Muévela en el Editor de HUD."
L["Your experience. Its left end is a darker shade."] = "Tu experiencia. Su extremo izquierdo es un tono más oscuro."
L["Your flight on a card: time left, the stops on a track, and the next stop."] = "Tu vuelo en una tarjeta: tiempo restante, las paradas en una pista y la siguiente parada."
L["Your focus target's casts on a bar of their own, colored by whether your interrupt is ready, with a tick where it comes off cooldown and a shield on casts you cannot interrupt. Your interrupt is the first you know of Pummel, Shield Bash, Kick, Counterspell, Earth Shock, Silence and Feral Charge. Move it in the HUD Editor."] = "Los lanzamientos de tu foco en su propia barra, coloreada según si tu interrupción está lista, con una marca donde sale de tiempo de reutilización y un escudo en los lanzamientos que no puedes interrumpir. Tu interrupción es la primera que conozcas de Aporrear, Azote de escudo, Patada, Contrahechizo, Choque de tierra, Silencio y Carga feral. Muévela en el Editor de HUD."
L["Your focus's name, tinted by class, with their class icon above the panel."] = "El nombre de tu foco, teñido por clase, con su ícono de clase arriba del panel."
L["Your focus, set with NF Focus: their timers keep counting while you fight someone else."] = "Tu foco, establecido con NF Focus: sus temporizadores siguen contando mientras peleas con otro."
L["Your game macros, not the Smart Macros, as one string to share."] = "Tus macros del juego, no las macros inteligentes, como una sola cadena para compartir."
L["Your global cooldown swept around the ring, and a ready ring once it is over."] = "Tu tiempo de reutilización global barrido alrededor del anillo, y un anillo de listo cuando termina."
L["YOUR GOLD"] = "TU ORO"
L["Your group in range: who is missing a blessing, who is running out, and who only needs their own."] = "Tu grupo al alcance: a quién le falta una bendición, a quién se le está agotando y quién solo necesita la suya."
L["Your group on a boss you are tanking."] = "Tu grupo en un jefe que estás tanqueando."
L["Your group's bars, with sample members."] = "Las barras de tu grupo, con miembros de ejemplo."
L["Your group's gear, talents and Naowh Score."] = "El equipo, talentos y Naowh Score de tu grupo."
L["Your group's healers and their mana, lowest first."] = "Los sanadores de tu grupo y su maná, el más bajo primero."
L["Your group's Naowh Score, gear, talents and stats."] = "El Naowh Score, equipo, talentos y estadísticas de tu grupo."
L["Your group's threat on your target."] = "La amenaza de tu grupo sobre tu objetivo."
L["Your healers' mana, with sample healers."] = "El maná de tus sanadores, con sanadores de ejemplo."
L["Your health under the threshold, with a healing item in your bags."] = "Tu salud por debajo del umbral, con un objeto de sanación en tus bolsas."
